CREATE OR REPLACE VIEW grc_pulse.pentest_risks_view AS
SELECT 
    r.id,
    r.organization_id,
    r.title,
    r.description,
    r.category,
    r.subcategory,
    r.inherent_likelihood,
    r.inherent_impact,
    r.inherent_score,
    r.context_priority_score,
    r.status,
    r.remediation_plan,
    r.due_date,
    r.external_reference,
    r.ai_analysis,
    r.discovered_at,
    r.created_at,
    r.updated_at,
    a.name as asset_name,
    a.asset_type,
    a.criticality as asset_criticality,
    
    CASE 
        WHEN r.external_reference LIKE 'pentest:%' 
        THEN substr(r.external_reference, 9, position('|' in r.external_reference) - 9)
        ELSE NULL 
    END as source_finding_id,
    CASE 
        WHEN r.external_reference LIKE '%project:%' 
        THEN substr(
            r.external_reference, 
            position('project:' in r.external_reference) + 8,
            position('|' in substr(r.external_reference, position('project:' in r.external_reference))) - 9
        )
        ELSE NULL 
    END as source_project_code
FROM grc_pulse.risk_items r
LEFT JOIN grc_pulse.assets a ON r.affected_asset_id = a.id
WHERE r.risk_source = 'penetration_test';




CREATE OR REPLACE VIEW grc_pulse.pentest_sync_stats AS
SELECT 
    organization_id,
    COUNT(*) as total_risks,
    SUM(CASE WHEN status = 'open' THEN 1 ELSE 0 END) as open_count,
    SUM(CASE WHEN status = 'in_progress' THEN 1 ELSE 0 END) as in_progress_count,
    SUM(CASE WHEN status = 'mitigated' THEN 1 ELSE 0 END) as mitigated_count,
    SUM(CASE WHEN status = 'closed' THEN 1 ELSE 0 END) as closed_count,
    SUM(CASE WHEN status = 'accepted' THEN 1 ELSE 0 END) as accepted_count,
    SUM(CASE WHEN inherent_score >= 80 THEN 1 ELSE 0 END) as critical_count,
    SUM(CASE WHEN inherent_score >= 60 AND inherent_score < 80 THEN 1 ELSE 0 END) as high_count,
    SUM(CASE WHEN inherent_score >= 30 AND inherent_score < 60 THEN 1 ELSE 0 END) as medium_count,
    SUM(CASE WHEN inherent_score < 30 THEN 1 ELSE 0 END) as low_count,
    MAX(updated_at) as last_sync_at,
    MIN(created_at) as first_sync_at
FROM grc_pulse.risk_items
WHERE risk_source = 'penetration_test'
GROUP BY organization_id;


